const body = $input.first().json.body ?? $input.first().json;
const { social_account_id, platform_id, date } = body;

if (!social_account_id || !platform_id) {
  throw new Error('Missing required fields: social_account_id, platform_id');
}

const snapshotDate = date ?? new Date().toISOString().split('T')[0];
console.log('[DATIAM:analytics] Syncing account:', social_account_id, 'date:', snapshotDate);

return [{ json: { social_account_id, platform_id, snapshot_date: snapshotDate } }];

